def compare_csv_files(file1_path: str, file2_path: str) -> Dict[str, List[Dict]]:
    """
    Compare two CSV files line by line and generate a detailed difference report.

    Args:
        file1_path: Path to the first CSV file.
        file2_path: Path to the second CSV file.

    Returns:
        A dictionary containing two lists:
        - 'differences_in_file1': Differences found in file1 (not in file2)
        - 'differences_in_file2': Differences found in file2 (not in file1)
        Each difference is represented as a dictionary with:
        - 'line_number': The line number in the respective file
        - 'status': 'added' or 'removed'
        - 'content': The line content as a dictionary (for CSV data)
    """
    # Read both CSV files into DataFrames
    try:
        df1 = pd.read_csv(file1_path)
        df2 = pd.read_csv(file2_path)
    except Exception as e:
        return {"error": str(e)}

    # Get the number of rows in each file
    len1, len2 = len(df1), len(df2)

    # Determine which file has more rows
    if len1 > len2:
        # File1 has more rows - check for differences in file1
        differences_in_file1 = []
        for i in range(len2, len1):
            line = df1.iloc[i].to_dict()
            differences_in_file1.append({
                'line_number': i + 1,  # +1 because pandas uses 0-based indexing
                'status': 'removed',
                'content': line
            })

        # Check for differences in file2 (rows in file2 not in file1)
        differences_in_file2 = []
        for i in range(len1):
            if i >= len2:
                break
            if not df1.iloc[i].equals(df2.iloc[i]):
                line1 = df1.iloc[i].to_dict()
                line2 = df2.iloc[i].to_dict()
                differences_in_file2.append({
                    'line_number': i + 1,
                    'status': 'changed',
                    'content': {
                        'file1': line1,
                        'file2': line2
                    }
                })

        # Check for rows in file2 that don't exist in file1 (if file2 is longer)
        if len2 > len1:
            for i in range(len1, len2):
