            line = df2.iloc[i].to_dict()
            differences_in_file2.append({
                'line_number': i + 1,
                'status': 'added',
                'content': line
            })

        # Check for differences in file1 (rows in file1 not in file2)
        differences_in_file1 = []
        for i in range(len2):
            if i >= len1:
                break
            if not df1.iloc[i].equals(df2.iloc[i]):
                line1 = df1.iloc[i].to_dict()
                line2 = df2.iloc[i].to_dict()
                differences_in_file1.append({
                    'line_number': i + 1,
                    'status': 'changed',
                    'content': {
                        'file1': line1,
                        'file2': line2
                    }
                })

    else:
        # Files are same length - just check for differences in each row
        differences_in_file1 = []
        differences_in_file2 = []

        for i in range(len1):
            if not df1.iloc[i].equals(df2.iloc[i]):
                line1 = df1.iloc[i].to_dict()
                line2 = df2.iloc[i].to_dict()
                differences_in_file1.append({
                    'line_number': i + 1,
                    'status': 'changed',
                    'content': {
                        'file1': line1,
                        'file2': line2
                    }
                })
