    if report['differences_in_file2']:
        print("\nDifferences in File2 (not in File1 or changed):")
        for diff in report['differences_in_file2']:
            print(f"\nLine {diff['line_number']}: {diff['status'].upper()}")
            if diff['status'] == 'changed':
