Here's a self-contained Python function that uses pytesseract to OCR an image, converts the extracted text to a target encoding, and — if OCR returns no text — falls back to extracting image comments/metadata (EXIF, PNG tEXt, JPEG comment, XP* fields). It returns a tuple (text, source) where source is 'ocr', 'comment', or 'none'.

Make sure you have pytesseract and Pillow installed (pip install pytesseract pillow) and that Tesseract is installed on your system.

```python
from typing import Tuple, Optional, Any
import pytesseract
from PIL import Image, ExifTags


def ocr_extract_with_fallback(
    image_path: str,
    lang: Optional[str] = None,
    tesseract_cmd: Optional[str] = None,
    target_encoding: str = 'utf-8'
) -> Tuple[str, str]:
    """
    Open an image, perform OCR with pytesseract, convert encoding to target_encoding,
    and if OCR yields no useful text, try to extract image comments/metadata as a fallback.

    Returns:
        (text, source) where source is one of: 'ocr', 'comment', 'none'.
    Parameters:
        image_path: path to the image file
        lang: optional tesseract language code(s), e.g. 'eng' or 'eng+fra'
        tesseract_cmd: optional path to the tesseract executable (pytesseract.pytesseract.tesseract_cmd)
        target_encoding: encoding to normalize the returned text to (default 'utf-8')
    """
    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    def _normalize_text(value: Any) -> Optional[str]:
        # Accepts str or bytes (or iterable of ints -> bytes), returns a str decoded/normalized
        if value is None:
            return None
        if isinstance(value, tuple) or isinstance(value, list):
            # sometimes XP* fields are sequences of integers
            try:
                value = bytes(value)
            except Exception:
                value = b''
        if isinstance(value, bytes):
            # Try common decodings in order
            # Handle EXIF UserComment header if present
            if value.startswith(b'ASCII\x00\x00\x00'):
                try:
                    return value[8:].decode('ascii', errors='replace').encode(target_encoding, errors='replace').decode(target_encoding, errors='replace')
                except Exception:
                    pass
            if value.startswith(b'UNICODE\x00') or value.startswith(b'UNICODE\x00\x00'):
                # EXIF UNICODE often uses UTF-16
                try:
                    return value[8:].decode('utf-16', errors='replace').encode(target_encoding, errors='replace').decode(target_encoding, errors='replace')
                except Exception:
                    pass
            # Try typical encodings
            for enc in ('utf-8', 'utf-16', 'utf-16le', 'utf-16be', 'cp1252', 'latin-1'):
                try:
                    return value.decode(enc, errors='replace').encode(target_encoding, errors='replace').decode(target_encoding, errors='replace')
                except Exception:
                    continue
            # As last resort, latin-1 decode
            try:
                return value.decode('latin-1', errors='replace').encode(target_encoding, errors='replace').decode(target_encoding, errors='replace')
            except Exception:
                return None
        elif isinstance(value, str):
            try:
                # Re-encode/normalize to the requested target encoding
                b = value.encode(target_encoding, errors='replace')
                return b.decode(target_encoding, errors='replace')
            except Exception:
                return value
        else:
            # Fallback: coerce to str
            try:
                s = str(value)
                b = s.encode(target_encoding, errors='replace')
                return b.decode(target_encoding, errors='replace')
            except Exception:
                return None

    try:
        img = Image.open(image_path)
    except Exception as exc:
        raise FileNotFoundError(f"Could not open image {image_path}: {exc}")

    # First attempt: OCR
    ocr_text = ""
    try:
        # Convert to RGB for better OCR compatibility (some formats)
        try:
            working = img.convert('RGB')
        except Exception:
            working = img
        ocr_text = pytesseract.image_to_string(working, lang=lang) if lang else pytesseract.image_to_string(working)
    except Exception:
        ocr_text = ""

    if ocr_text:
        normalized = _normalize_text(ocr_text)
        if normalized and normalized.strip():
            return normalized.strip(), 'ocr'

    # Fallback: attempt to extract comments/metadata
    # Gather candidate comment values from image.info and EXIF fields
    candidates = []

    # From PNG tEXt, JPEG info, etc.
    info = getattr(img, 'info', {}) or {}
    for k, v in info.items():
        # Common keys: 'comment', 'Comment', 'description', 'XML:com.adobe.xmp' etc.
        if isinstance(v, (str, bytes, tuple, list)):
            candidates.append(v)

    # EXIF fields
    try:
        exif = img.getexif()
    except Exception:
        exif = None

    if exif:
        # Map tag ids to names
        tag_map = {tid: ExifTags.TAGS.get(tid, tid) for tid in exif.keys()}
        for tid, val in exif.items():
            name = tag_map.get(tid, tid)
            # Common descriptive tags
            if name in ('UserComment', 'ImageDescription', 'XPComment', 'XPTitle', 'XPSubject', 'XPAuthor', 'Comments'):
                candidates.append(val)

    # Also check for legacy JPEG comment (PIL may store as app data in info or via "comment" key)
    if 'comment' in info:
        candidates.append(info.get('comment'))

    # Try candidates in order
    for cand in candidates:
        norm = _normalize_text(cand)
        if norm and norm.strip():
            return norm.strip(), 'comment'

    # Nothing found
    return "", 'none'
