    """
    Extract the first URL from the input text, fetch that page, and return its <title> text.

    Returns:
      - The page title string on success.
      - An error message string if no URL is found, the fetch fails, the response is not HTML,
        or a <title> tag cannot be located.

    Notes:
      - Recognizes URLs beginning with http:// or https:// (and 'www.' with implicit http://).
      - Trims common trailing punctuation from detected URLs.
    """
    if not text or not isinstance(text, str):
        return "Error: Input must be a non-empty string."

    # Find first http(s) URL or www... (we'll add scheme if needed)
    url_match = re.search(r'(https?://[^\s<>()]+|www\.[^\s<>()]+)', text, re.IGNORECASE)
    if not url_match:
        return "Error: No valid URL found in input."

    raw_url = url_match.group(0).rstrip('.,;:!?)]}\'"')  # strip common trailing punctuation
    if raw_url.startswith('www.'):
        raw_url = 'http://' + raw_url

    # Basic URL validation
    parsed = urlparse(raw_url)
    if not parsed.scheme or not parsed.netloc:
        return f"Error: Extracted text is not a valid URL: {raw_url}"

    headers = {
        "User-Agent": "Mozilla/5.0 (compatible; TitleFetcher/1.0; +https://example.com/bot)"
    }

    try:
        resp = requests.get(raw_url, headers=headers, timeout=timeout, allow_redirects=True)
    except requests.RequestException as e:
        return f"Error: Failed to fetch URL: {e}"

    if not resp.ok:
        return f"Error: HTTP error {resp.status_code} when fetching URL."

    content_type = resp.headers.get("content-type", "")
    if "html" not in content_type.lower():
        # still try to parse if content type is missing but content looks like HTML
        snippet = (resp.text or "")[:200].lower()
        if "<html" not in snippet and "<!doctype html" not in snippet:
            return f"Error: URL did not return an HTML page (Content-Type: {content_type!s})."

    # Parse HTML to find title
    try:
        soup = BeautifulSoup(resp.text, "html.parser")
    except Exception as e:
        return f"Error: Failed to parse HTML: {e}"

    title_tag = soup.title or soup.find("title")
    if not title_tag:
        # try og:title meta
        og = soup.find("meta", property="og:title")
        if og and og.get("content"):
            return og.get("content").strip()
        return "Error: No <title> tag found on the page."

    title_text = title_tag.string or title_tag.get_text()
    if not title_text:
        return "Error: <title> tag is empty."

    return title_text.strip()
